import assert from "node:assert/strict";
import {readFileSync,writeFileSync} from "node:fs";
import {createHash} from "node:crypto";

const records=[];
for(const [name,input] of [["baseline","build/profile/raw-baseline.c"],["candidate","build/profile/word-direct-v1.c"]]){
  const source=readFileSync(input,"utf8"),start=source.indexOf("Term io_print_run("),end=source.indexOf("\n}\n",start)+3;
  assert.ok(start>0&&end>start);
  const block=source.slice(start,end);
  assert.equal(block.split("  io_out(stdout, text, n);").length,2);
  assert.equal(block.split("  free(text);").length,2);
  const changed=block.replace("  io_out(stdout, text, n);","  if (strstr(text, \"\\\"type\\\":\\\"done\\\"\")) { moncontrol(0); _mcleanup(); }\n  io_out(stdout, text, n);")
    .replace("  free(text);","  if (strstr(text, \"\\\"type\\\":\\\"ready\\\"\")) moncontrol(1);\n  free(text);");
  const output=`build/profile/search-${name}-v1.c`,text=source.slice(0,start)+"extern void moncontrol(int);\nextern void _mcleanup(void);\n"+changed+source.slice(end)+"\nstatic void __attribute__((constructor)) rubend_search_profile_off(void) { moncontrol(0); }\n";
  writeFileSync(output,text,{flag:"wx"});
  records.push({name,input,output,inputSha256:createHash("sha256").update(source).digest("hex"),outputSha256:createHash("sha256").update(text).digest("hex")});
}
writeFileSync("build/profile/search-profile-inputs-v1.json",JSON.stringify({records,scope:"Profiling-only generated C. Sampling disabled at process construction, enabled after real ready, stopped and written before first native done. Search mathematics unchanged."},null,2)+"\n");
console.log(JSON.stringify(records));

