import assert from "node:assert/strict";
import {readFileSync,existsSync,writeFileSync} from "node:fs";
import {resolve} from "node:path";
import {Engine} from "../../apps/engine.mjs";

const [label,binary,prefix]=process.argv.slice(2),facelets=JSON.parse(readFileSync("docs/verification/portfolio-v1/exact-profile.json")).records[0].facelets;
process.env.RUBEND_JOINT_CACHE=resolve(".cache/joint/phase1-v1.raw");
process.env.GMON_OUT_PREFIX=resolve(prefix);
const engine=new Engine({binary:resolve(binary)}),events=[],started=performance.now();
let initializationMs,passed=false;
try{
  await engine.ready(120000);initializationMs=performance.now()-started;
  const generation=engine.generation;
  await new Promise((done,fail)=>{
    engine.solve({facelets,mode:"exact",budgetMs:2000},event=>{events.push(event);if(event.type==="error"||event.type==="invalid")fail(Error(JSON.stringify(event)));if(event.type==="done")done();}).catch(fail);
  });
  const last=events.at(-1);assert.notEqual(last.reason,"time_limit");assert.ok(Number.isInteger(last.nodes)&&last.nodes>0);
  assert.equal(engine.generation,generation);assert.ok(events.some(e=>e.type==="candidate"));
  const gmon=`${resolve(prefix)}.${engine.child.pid}`;assert.ok(existsSync(gmon));
  passed=true;
  console.log(JSON.stringify({label,passed,initializationMs,facelets,requestedMs:2000,done:last,gmon,purpose:"Unreported first hard-job CPU profile after initialization. Not a five-round warmed timing or strength comparison."}));
}finally{
  await engine.close();
  writeFileSync(`build/profile/search-${label}-events-v1.json`,JSON.stringify({passed,events},null,2)+"\n");
}
